ROOT = r'c:\Users\tamir\Documents\UFCG\ciframe'
sys.path.insert(0, ROOT)
sys.modules['flask'] = MagicMock()

import main


def rota(nome):
    for chamada in main.app.route.return_value.call_args_list:
        funcao = chamada.args[0]
        if getattr(funcao, '__name__', None) == nome:
            return funcao
    raise AssertionError('rota nao encontrada: %s' % nome)


