with open(os.path.join(ROOT, 'research', 'baseline_similares_sequencias.json'), encoding='utf-8') as f:
    baseline = json.load(f)

for item in baseline:
    valor = item['sequencia'].replace(' ', ',')
    paginas = []
    pagina = 1
    while True:
        def args_get(key, default=None, valor=valor, pagina=pagina):
            return {'sequencia': valor, 'pagina': str(pagina)}.get(key, default)

