    { 'acorde': 'A#', 'cor': '#76aadb' },
    { 'acorde': 'Am', 'cor': '#89c0e9' },
    { 'acorde': 'A#m','cor': '#89c0e9' },
    { 'acorde': 'A7', 'cor': '#6c9ecc' },
    { 'acorde': 'A#7','cor': '#6c9ecc' }];
  var acordesB = [
    { 'acorde': 'B',  'cor': '#a3bd31' },
    { 'acorde': 'Bm', 'cor': '#cdd54f' },
    { 'acorde': 'B7', 'cor': '#96b02f' }];
  var vm = this;
  vm.acordes = [];
