      controller: function(name, fn) {
        captured = fn;
      }
    };
  }
};

const controllerPath = path.join(process.cwd(), 'static/assets/js/controllers/sequencia.js');
eval(fs.readFileSync(controllerPath, 'utf8'));

function createHttp() {
  const calls = [];

  function chain(call) {
    return {
      success: function(cb) {
        call.success = cb;
        return this;
      },
      error: function(cb) {
        call.error = cb;
        return this;
      }
    };
  }

  return {
    calls: calls,
    get: function(url, config) {
      const call = { method: 'GET', url: url, config: config };
      calls.push(call);
      return chain(call);
    },
    post: function(url, body, config) {
      const call = { method: 'POST', url: url, body: body, config: config };
      calls.push(call);
      return chain(call);
    },
    last: function() {
      return calls[calls.length - 1];
    }
  };
}

function createProgressFactory() {
  const progress = {
    started: 0,
    completed: 0,
    start: function() { progress.started += 1; },
    complete: function() { progress.completed += 1; }
  };
  return {
    createInstance: function() { return progress; },
    progress: progress
  };
}

